searchDatas1[49] = ['','Подключите сканер к компьютеру с помощью кабеля USB.','./tb_ip_01.html', '	Подключите сканер к компьютеру с помощью кабеля USB.	Причина 	Проблема может быть вызвана следующим:	Сканер не подключен к компьютеру с помощью кабеля USB	Драйвер сканера не установлен	Сканер не включен	Сканер, подключенный к компьютеру, не поддерживается Инструментом настройки IP-адреса	Решение 	Выполните следующее:	Подключите сканер к компьютеру с помощью кабеля USB, который прилагается к сканеру.	Установите драйвер сканера.	Для получения дополнительной информации смотрите руководство оператора сканера.	Включите сканер.	Проверьте, какие модели сканеров поддерживаются Инструментом настройки IP-адреса.	Для получения подробной информации смотрите 	Поддерживаемые модели сканера.'];
