searchDatas1[56] = ['','IP-адрес имеет неверный формат.','./tb_ip_18.html', '	IP-адрес имеет неверный формат.	Причина 	IP-адрес для IPv6 имеет неверный формат.	Решение 	Введите IP-адрес в верном формате.	Each xxxx in xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx должно быть значением от 0 до ffff.	Проверьте следующее и повторите попытку.	В полях ввода указано значение шестнадцатеричным числом	Менее двух раз использована сокращенная форма (::)	В полях ввода нет пробелов'];
searchDatas1[57] = ['','Длина префикса подсети имеет неверный формат.','./tb_ip_16.html', '	Длина префикса подсети имеет неверный формат.	Причина 	Длина префикса подсети для IPv6-адреса имеет неверный формат.	Решение 	Введите длину префикса подсети в верном формате.	Может быть введено значение от 3 до 128.'];
