searchDatas1[59] = ['','Шлюз по умолчанию имеет неверный формат.','./tb_ip_19.html', '	Шлюз по умолчанию имеет неверный формат.	Причина 	Шлюз по умолчанию для IPv6 имеет неверный формат.	Решение 	Введите шлюз по умолчанию в верном формате.	Each xxxx in xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx должно быть значением от 0 до ffff.	Проверьте следующее и повторите попытку.	В полях ввода указано значение шестнадцатеричным числом	Менее двух раз использована сокращенная форма (::)'];
searchDatas1[60] = ['','Шлюз по умолчанию или маска подсети недействительны.','./tb_ip_10.html', '	Шлюз по умолчанию или маска подсети недействительны.	Причина 	Установлен недопустимый шлюз по умолчанию или маска подсети.	Решение 	Введите действительный шлюз по умолчанию или маску подсети.	Каждая переменная xxx в xxx.xxx.xxx.xxx должна быть значением от 0 до 255.	Убедитесь, что введенные значения совпадают со значениями, указанными для шлюза по умолчанию или маски подсети, а затем повторите попытку.'];
searchDatas1[61] = ['','Не выполнен ввод имени сканера.','./tb_ip_14.html', '	Не выполнен ввод имени сканера.	Причина 	Не выполнен ввод имени сканера.	Решение 	Введите один или несколько символов в поле [Имя сканера].	Доступны буквенно-числовые символы, "-" (дефис), "_" (подчеркнутая линия) и пробелы.'];
searchDatas1[62] = ['','Этот сканер используется другим пользователем или приложением.','./tb_ip_12.html', '	Этот сканер используется другим пользователем или приложением.	Причина 	Сканер используется другим приложением или другим пользователем.	Решение 	Убедитесь, что другое приложение или пользователь не использует сканер.	Кроме того, выполните выход из приложения, которое использует сканер.	Если проблема сохраняется, выключите сканер и снова включите его.'];
